from django.http import JsonResponse
from django.contrib.auth.decorators import login_required
from django.views.decorators.cache import cache_page
from django.views.decorators.vary import vary_on_cookie, vary_on_headers
from .models import UserFinancialPortfolio

# vary_on_cookie ensures the cache key is segmented per user session
@login_required
@vary_on_cookie
@vary_on_headers('Authorization')
@cache_page(60 * 15)
def user_portfolio_summary(request):
    portfolio = UserFinancialPortfolio.objects.get(user=request.user)
    data = {
        'user_id': request.user.id,
        'account_holder': f"{request.user.first_name} {request.user.last_name}",
        'bank_account_mask': portfolio.account_number_masked,
        'total_balance_usd': str(portfolio.total_balance),
        'holdings': portfolio.holdings_summary
    }
    return JsonResponse(data)
